import React, { ChangeEvent } from 'react';
import { InlineField, InlineSwitch, Input, SecretInput, TextArea } from '@grafana/ui';
import { DataSourcePluginOptionsEditorProps } from '@grafana/data';
import { DuckDBDataSourceOptions, SecureJsonData } from '../types';

interface Props extends DataSourcePluginOptionsEditorProps<DuckDBDataSourceOptions, SecureJsonData> {}

export function ConfigEditor(props: Props) {
  const { onOptionsChange, options } = props;
  const { jsonData, secureJsonFields, secureJsonData } = options;

  const onPathChange = (event: ChangeEvent<HTMLInputElement>) => {
    onOptionsChange({
      ...options,
      jsonData: {
        ...jsonData,
        path: event.target.value,
      },
    });
  };

  const onInitSqlChange = (event: ChangeEvent<HTMLTextAreaElement>) => {
    onOptionsChange({
      ...options,
      jsonData: {
        ...jsonData,
        initSql: event.target.value,
      },
    });
  };

  const onHomeDirectoryChange = (event: ChangeEvent<HTMLInputElement>) => {
    onOptionsChange({
      ...options,
      jsonData: {
        ...jsonData,
        homeDirectory: event.target.value,
      },
    });
  };

  const onReadOnlyChange = (event: ChangeEvent<HTMLInputElement>) => {
    onOptionsChange({
      ...options,
      jsonData: {
        ...jsonData,
        readOnly: event.currentTarget.checked,
      },
    });
  };

  const onMaxOpenConnsChange = (event: ChangeEvent<HTMLInputElement>) => {
    const value = parseInt(event.target.value, 10);
    onOptionsChange({
      ...options,
      jsonData: {
        ...jsonData,
        maxOpenConns: isNaN(value) ? 0 : value,
      },
    });
  };

  // Secure field (only sent to the backend)
  const onMotherDuckTokenChange = (event: ChangeEvent<HTMLInputElement>) => {
    onOptionsChange({
      ...options,
      secureJsonData: {
        motherDuckToken: event.target.value,
      },
    });
  };

  const onResetMotherDuckToken = () => {
    onOptionsChange({
      ...options,
      secureJsonFields: {
        motherDuckToken: false,
      },
      secureJsonData: {
        motherDuckToken: '',
      },
    });
  };

  return (
    <>
      <InlineField label="Database name" labelWidth={24} interactive tooltip={'path to DuckDB file or MotherDuck database string or leave blank to use in-memory database'}>
        <Input
          id="config-editor-path"
          onChange={onPathChange}
          value={jsonData.path}
          placeholder="e.g. md:sample_data or /path/to/database.duckdb or leave blank to use in-memory database"
          width={40}
        />
      </InlineField>
      <InlineField label="Init SQL" labelWidth={24} interactive
                     tooltip={'(Optional) SQL to run when connection is established'}>
          <TextArea
              id="config-editor-init-sql"
              onChange={onInitSqlChange}
              value={jsonData.initSql || ''}
              placeholder="e.g. INSTALL 'httpfs'; LOAD 'httpfs';"
              width={60}
              rows={5}
          />
      </InlineField>
      <InlineField label="DuckDB home directory" labelWidth={24} interactive
        tooltip={'Directory DuckDB installs extensions and stores secrets under. Leave blank to use the Grafana data directory, which Grafana 12.4 and later no longer pass on to plugins.'}>
        <Input
          id="config-editor-home-directory"
          onChange={onHomeDirectoryChange}
          value={jsonData.homeDirectory || ''}
          placeholder="/var/lib/grafana"
          width={40}
        />
      </InlineField>
      <InlineField label="Read-only" labelWidth={24} interactive
        tooltip={'Open the database without write access, so a DuckDB file keeps no write lock and other processes can still write to it. Not available for an in-memory database.'}>
        <InlineSwitch
          id="config-editor-read-only"
          value={jsonData.readOnly ?? false}
          onChange={onReadOnlyChange}
        />
      </InlineField>
      <InlineField label="Max Connections" labelWidth={24} interactive tooltip={'Maximum number of concurrent database connections (default: 25).'}>
        <Input
          id="config-editor-max-open-conns"
          type="number"
          onChange={onMaxOpenConnsChange}
          value={jsonData.maxOpenConns ?? ''}
          placeholder="25"
          width={40}
        />
      </InlineField>
      <InlineField label="MotherDuck Token" labelWidth={24} interactive tooltip={'MotherDuck Token'}>
        <SecretInput
          required
          id="config-editor-md-token"
          isConfigured={secureJsonFields.motherDuckToken}
          value={secureJsonData?.motherDuckToken}
          placeholder="Enter your MotherDuck token"
          width={40}
          onReset={onResetMotherDuckToken}
          onChange={onMotherDuckTokenChange}
        />
      </InlineField>


    </>
  );
}
